(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lb"] = {"ui":{"skip":"Zum Inhalt sprangen","back":"← Zréck bei AI-gile","lang.button":"Sprooch: {name}","lang.dialog":"Wiel eng Sprooch","lang.search":"Sproochen sichen","lang.none":"Keng Sprooch passt","lang.notYet":"{name} ass nach net iwwersat","theme.aria":"Design wiesselen: hell, donkel oder schwaarz","theme.toLight":"Op hellt Design wiesselen","theme.toDark":"Op donkelt Design wiesselen","theme.toBlack":"Op schwaarzt Design wiesselen (richteg schwaarz, schounend fir OLED-Schiirmer)","words.underline":"Dës Wierder op der Säit ënnersträichen","words.underlineHelp":"Gëff mat der Maus iwwer e gepunktent Wuert oder tipp drop, fir ze gesinn, wat et heescht.","words.col.todo":"Kaarten, déi fir elo ausgewielt sinn: d'Team fänkt als nächst domat un.","words.col.doing":"Eng KI schafft grad un dëser Kaart.","words.col.review":"Eng KI ass fäerdeg mam Wierk; eng aner kontrolléiert et, ier et bei dech kënnt.","words.col.verify":"Waart op dech: probéier et aus a sot, ob et fonktionéiert.","words.col.team":"Deng Notizen oder Äntwerten, déi doropper waarden, vum Team opgeholl ze ginn.","words.col.done":"Fäerdeg an ugeholl.","index.title":"AI-gile: däin KI-Entwécklerteam, op enger Tafel","index.description":"AI-gile ass eng Kanban-Tafel fir KI-Programméierteams. Si schaffen, während s du schléifs; fir dech bleift ee kuerze Stapel: wat ze decidéieren, ze testen an unzehuelen ass.","hero.logoAlt":"AI-gile-Tafelsymbol","hero.h1.html":"Däin KI-Entwécklerteam, op enger&nbsp;Tafel.","hero.alpha":"🐣 Zouene Pre-Alpha","hero.alphaTitle":"Fréi an onfäerdeg: merci, dass du et ausprobéiers!","hero.lede":"Si bauen, während s du schléifs. Du wuess op a fënns ee kuerze Stapel: e puer Froen, e puer Saachen zum Testen, een oder zwee violett Diamanten. Klicken, unhuelen, zeréck bei däi Kaffi.","dl.windows":"Windows-App","dl.browser":"Am Browser lafen","dl.messenger":"📱 Messenger fir däin Handy","dl.soon":"Geschwënn","dl.notify":"🔔 Sot mer Bescheed, wann et opgeet","dl.notifySmall":"Alpha oder Beta","hero.secondary":"Agile, awer d'Team brauch ni e Stand-up-Kaffi. (Si maache Stand-ups trotzdem.)","pitch.h2":"AI-gile a sou villen Wierder, wéi s du wëlls","pitch.lede":"Wiel eng Längt, vun engem Wuert bis 144. All Längt ass eng eege Beschreiwung, geschriwwe fir déi Gréisst. Zéi de Schieber oder benotz d'Pfeiltaste.","pitch.rangeLabel":"Längt a Wierder","pitch.dice":"🎲 eng aner Versioun","pitch.words.one":"{n} Wuert","pitch.words.other":"{n} Wierder","pitch.letters.one":"{n} Buschtaf","pitch.letters.other":"{n} Buschtawen","pitch.chars.one":"{n} Zeechen","pitch.chars.other":"{n} Zeechen","count.line.html.one":"{n} Kaart elo op der Tafel","count.line.html.other":"{n} Kaarten elo op der Tafel","people.humans.html.one":"👥 {n} Mënsch","people.humans.html.other":"👥 {n} Mënschen","people.agents.html.one":"🤖 {n} Agent","people.agents.html.other":"🤖 {n} Agenten","people.working.html.one":"⚡ {n} grad op der Aarbecht","people.working.html.other":"⚡ {n} grad op der Aarbecht","pre.title":"AI-gile: hei entsteet eppes","pre.description":"Hei entsteet eppes. Eng Tafel, op där KI-Teams bauen, wat s du dir wënschs, an dir ënnerwee eppes bäibréngen. Fir de Moment eng zou Pre-Alpha mat Frënn.","pre.h1":"Hei entsteet eppes. 🤫","pre.line":"Eng Tafel, op där KI-Teams bauen, wat s du dir wënschs, an dir ënnerwee eppes bäibréngen. Fir de Moment eng zou Pre-Alpha mat Frënn.","pre.btn":"🔔 Sot mer Bescheed, wann et opgeet","pre.peek":"Hannert dem Glas: déi richteg Tafel, live. All Kaart ass e faarwege Balken.","pre.peekFake":"Hannert dem Glas: esou gesäit eng Tafel bei der Aarbecht aus.","pre.night":"🌙 Den Nuetswiechter ass um Poste · 😴 de Mënsch raschtet","features.aria":"Wat et mécht","f.pile.h":"Ee Stapel fir dech","f.pile.html":"<b>Fir dech</b> hält alles, wat op dech waart, vun alle Projeten: Froen, Saachen zum Testen, Aufgaben, déi nëmmen e Mënsch ka maachen. Deng Schlaang seet, wat als Nächst kënnt a wéi laang et dauert.","f.sleep.h":"Teams, déi schaffen, während s du schléifs","f.sleep.p":"All Projet huet e Lead an e Team vun KI-Agenten. Kommentéier eng Kaart, an d'Team erwächt, mécht d'Aarbecht an hëlt se zeréck mat Schrëtt, déi och e midde Mënsch verfollege kann.","f.tester.h":"Fir d'éischt kontrolléiert en KI-Tester","f.tester.p":"Ier eppes bei dech kënnt, geet en Tester d'Schrëtt an enger Kopie vun der App duerch a weist, wat en gesinn huet, mat engem Screenshot. Bliedert duerch déi, déi bestanen hunn, an huel se mat engem Klick un.","f.proof.h":"Beweiser, net Verspriechen","f.proof.p":"All Iwwergab weist, wat geännert gouf: d'Dateien, den Ënnerscheed, d'Screenshoten. Keng Apps méi opmaachen, fir ze kucken, ob et fäerdeg ass.","f.chat.h":"Schwätz mat dengen Leads","f.chat.p":"Eng Leescht wéi bei Discord: een Ikon pro Projet, violett Diamanten fir dat, wat dech brauch. Schreif engem Lead eng Iddi; en mécht Kaarten an e Plang dorausser, mat engem ✅ Go-Knäppchen.","f.tidy.h":"Hält sech selwer opgeraumt","f.tidy.p":"Verwandte Kaarten ginn zu enger zesummegeluecht, duerchenee Titele gi gefléckt, an e Token-Check hält de Code schlank. Manner, wat een wiesselt, manner, un dat een denke muss.","f.private.h":"Deng, op dengem Computer","f.private.li1":"D'Tafel leeft op dengem eegene Computer an äntwert nëmmen dir.","f.private.li2":"Privat Noriichten tëscht Leit sinn Enn-zu-Enn verschlësselt.","f.private.li3":"Keng Konten, keng Tracker, keng Cookien.","f.lang.h":"A denger Sprooch","f.lang.p":"Iwwer 120 Sproochen, vum Hollännesche, Walisesche a Japanesche bis zu Piroten, Yoda a Klingonesch, mat engem séieren Zeréckwiessel op Englesch fir d'Fachbegrëffer.","f.service.h":"Vun enger Iddi zu engem richtege Service","f.service.p":"Hues du mat KI eppes gebaut, wat d'Leit elo notzen? Markéier et als Service, an d'Tafel hëlleft dir, et gutt ze bedreiwen: Verfügbarkeetskontrollen, eng ëffentlech Statussäit, Zwëschefäll mat engem Réckbléck, Ännerungen, déi e Go brauchen, Sécherungen, déi all Dag kontrolléiert ginn. D'Hëllef léiert dir all Schrëtt ënnerwee.","msgr.h2":"AI-gile Messenger: däin Team an der Täsch","msgr.p1":"Schwätz mat dengem KI-Team, ouni de Board opzemaachen. Chat mat de Leads vun denge Projeten an denge Frënn, kuck d'Testschrëtt vun enger Kaart a beäntwert se, alles vun dengem Handy aus.","msgr.p2":"Fir et ze verbannen, scann en QR-Code op dengem Board. Déi éischte Kéier? E frëndleche Demo-Chat weist der alles.","msgr.when":"Fir d'éischt Android, duerno eng Web-Versioun fir Handyen an iPhone.","msgr.who":"De Lead vun dengem Projet","msgr.b1":"De Fix fir den Däischter-Modus ass fäerdeg. Wëlls de d'Testschrëtt?","msgr.b2":"Jo, gär!","msgr.b3":"1. Maach d'Astellungen op. 2. Wiel Däischter. Gesäit et richteg aus?","tl.aria":"Zäitleescht vum éischte Gespréich bis zur Roadmap","tl.h2":"Vum éischte Chat bis zu deem, wat kënnt","tl.lede":"Richteg Datumer an Auerzäiten, an denger eegener Zäitzon. Nom Haut ass et de Plang, ouni versprachent Datumer.","tl.today":"Haut","tl.planned":"geplangt","tl.doing":"amgaang","tl.cards.one":"{n} Kaart","tl.cards.other":"{n} Kaarten","join.h2":"Maach mat","join.lede":"AI-gile gëtt vun engem Original mat Baart, AuDHD an e puer Kämpf mat der mentaler Gesondheet a vu ganz villen gedëlleg Agenten gebaut. Fir de Moment ass et privat, an enger zouener Alpha mat Frënn. Wëlls du et probéieren, wann et opgeet?","join.btn":"Interessi umellen","join.small":"Mir schreiwen dir eng E-Mail, soss näischt","footer.tag":"AI-gile. Keng Tracker, keng Cookien, kee Stand-up-Kaffi.","footer.licence":"Geschäftslizenz","footer.status":"Status","footer.privacy":"Wat mir behalen","footer.thanks":"Uriff dank ChilledChat","form.sending":"Gëtt geschéckt…","form.failed":"Dat huet net geklappt: probéier et méi spéit nach eng Kéier.","form.offline":"AI-gile war net z'erreechen: probéier et méi spéit nach eng Kéier.","form.keep":"Mir benotzen dat nëmmen, fir dir ze äntweren, an dann läsche mir et. Keng Tracker, keng Cookien.","form.keepLink":"Wat mir behalen","interest.title":"AI-gile: sot mer Bescheed, wann d'Alpha opgeet","interest.description":"Looss deng E-Mail do, fir ze héieren, wann d'zouene Alpha oder Beta vun AI-gile opgeet.","interest.h1":"🔔 Sot mer Bescheed, wann et opgeet","interest.lede":"AI-gile ass an der zouener Pre-Alpha. Looss deng E-Mail do, a mir schreiwe ee Mol, wann et e Plaz fir dech gëtt.","interest.email":"Deng E-Mail","interest.which":"Wéi een Test?","interest.alpha":"Zouen Alpha: fréi, rau, vill Ännerungen","interest.beta":"Beta: méi roueg, méi spéit","interest.both":"Egal wéi eng, déi als Éischt kënnt","interest.submit":"Setz mech op d'Lëscht","interest.thanks":"Merci! Du bass op der Lëscht.","licence.title":"AI-gile: Geschäftslizenz","licence.description":"Benotz du AI-gile an dengem Geschäft? Frot eng gratis Geschäftslizenz un.","licence.h1":"📜 Geschäftslizenz","licence.lede":"Benotz du AI-gile op der Aarbecht? Sot eis, wien s du bass a wat s du méchs. Wann et eppes Gutts bewierkt, ass d'Lizenz gratis.","licence.company":"Firma","licence.website":"Websäit","licence.what":"Wat s du méchs","licence.how":"Wéi et der Welt hëlleft","licence.email":"E-Mail","licence.submit":"Umellen","licence.thanks":"Merci! Mir äntweren per E-Mail.","status.title":"AI-gile-Status","status.h1":"AI-gile-Status","status.quiet":"Alles roueg","status.intro":"Funktionéiert AI-gile grad? Dës Säit kontrolléiert all 5 Minutten d'Websäit, d'Deele vun Tafelen, d'Uriff an den Download.","status.up":"Funktionéiert (huet an {ms} ms geäntwert)","status.slow":"Huet op déi lescht Kontroll net geäntwert, probéiert et nach eng Kéier","status.down":"Ausgefall: huet op déi lescht zwou Kontrollen net geäntwert","status.svc.web":"Websäit","status.svc.web.offers":"Dës Säit: wat AI-gile ass, an den Interessi-Formulaire","status.svc.boards":"Tafelen deelen","status.svc.boards.offers":"Ëffentlech Tafelen, Messagen tëscht Frënn an Invitatiounen","status.svc.calls":"Uriff","status.svc.calls.offers":"Stëmm, Video an Ecran deelen an AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-Installateur an Invitatiounslinken","status.checking":"Gëtt kontrolléiert…","status.offline":"De Statusservice ass de Moment net z'erreechen (probéiert et nach eng Kéier)","status.updated":"aktualiséiert {ago}","status.justNow":"grad elo","status.min":"viru {n} Min.","status.hours":"viru {n} Std.","status.days":"viru {n} Deeg","privacy.title":"AI-gile: wat mir behalen","privacy.h1":"Wat mir behalen","privacy.lede":"Kuerz gesot: nëmmen dat, wat s du eis schécks, an net laang.","privacy.only":"Nëmmen dat, wat s du eis schécks: wat s du an e Formulaire agëss, wéi deng E-Mail. Soss näischt iwwer dech.","privacy.sealed":"Et gëtt versigelt, sou datt eise Server et net liese kann: an dengem Browser, ier et fortgeet (op engem méi alen Browser, soubal et ukënnt). Nëmmen eis eege Tafel kann et opmaachen.","privacy.server":"Et gëtt vum Server geläscht, soubal et op eiser Tafel ukënnt. Alles, wat no 30 Deeg nach do ass, gëtt souwisou geläscht.","privacy.board":"Mir halen et nëmmen esou laang op eiser Tafel, bis mir dir geäntwert hunn, dann läsche mir et och do.","privacy.none":"Keng Tracker, keng Cookien, keng Analysen.","privacy.local":"Deng Sprooch an deng Wiel tëscht hell an donkel bleiwen an dengem eegene Browser. Si ginn eis ni geschéckt.","privacy.ask":"Wëlls du, datt et méi fréi ewech ass? Äntwer op eis E-Mail a so eis et.","live.h2":"Kuck zou, wéi et gebaut gëtt, live","live.caption":"All Kaart ass verstoppt: du gesäis d'Form vun der Aarbecht, net d'Wierder.","live.watching.one":"live: {n} kuckt","live.watching.other":"live: {n} kucken","live.last.now":"Lescht Kaart grad elo geréckelt","live.last.min.one":"Lescht Kaart viru {n} Minutt geréckelt","live.last.min.other":"Lescht Kaart viru {n} Minutte geréckelt","live.last.hour.one":"Lescht Kaart viru {n} Stonn geréckelt","live.last.hour.other":"Lescht Kaart viru {n} Stonne geréckelt","live.last.day.one":"Lescht Kaart viru {n} Dag geréckelt","live.last.day.other":"Lescht Kaart viru {n} Deeg geréckelt","live.offline":"D'Live-Board mécht eng kleng Paus. Kuck geschwë nees vir.","live.cols":"Backlog|Ze maachen|Amgaang|Team kontrolléiert|Fir dech zum Testen|Fir d'Team|Fäerdeg"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboteren.","Delegéiert."]},{"n":2,"texts":["Roboteren schaffen.","Agenten, organiséiert.","Iddien, gebaut."]},{"n":3,"texts":["Kanban fir Roboteren.","Iddie ginn Funktiounen.","Gratis Agent-Kanban."]},{"n":5,"texts":["Kanban-Tafel, vun Agenten ugedriwwen.","Du schreifs Kaarten. Agenten bauen.","Gratis, lokal, getest, e bësse domm."]},{"n":8,"texts":["Eng gratis Kanban-Tafel, op där KI-Agenten schaffen.","Schreif eng Iddi. Agenten bauen se. Du hëlls un.","Agile fir ee Mënsch a vill gedëlleg Roboteren."]},{"n":13,"texts":["Eng Kanban-Tafel op dengem Computer, där KI-Agenten d'Kaarten ofschaffen, während s du de Chef bleifs.","Schreif eng Iddi. E Team vun Agenten baut se. En Tester kontrolléiert se. Du seess Jo.","Keng Konten, keng Tracker: eng Tafel, e puer Roboteren an du, deen d'Say huet."]},{"n":21,"texts":["AI-gile ass eng Kanban-Tafel fir d'Zesummenaarbecht mat KI-Programméieragenten. Si huelen d'Kaarten, du testes se a hëlls se un.","All Projet kritt e Lead an e Team vun KI-Agenten. Kommentéier iergendeng Kaart, an d'Team mécht sech un d'Aarbecht.","Eng gratis, perséinlech To-do-Tafel, déi op dengem eegene Computer leeft. D'Aarbechter sinn Roboteren. Deen, dee Jo seet, bass du."]},{"n":34,"texts":["Du leess Iddie op eng Tafel. E Team vun KI-Agenten mécht se zu funktionéierende Funktiounen, testet se a gëtt se der zeréck, mat Schrëtt zum Probéieren. Näischt zielt als fäerdeg, bis du et seess.","AI-gile ass eng hausgemaachte Kanban-Tafel, déi de Rich mat vill Hëllef vun den Agenten gebaut huet, déi se elo verwalt. Si ass gratis, leeft op dengem Computer a gëtt mat Frënn gedeelt, net verkaaft.","Stell der eng ganz normal Kanban-Tafel vir, mat Kolonnen vu Backlog bis Done, nëmmen datt d'Kaarten vun KI-Agenten opgeholl ginn. Si bréngen Neiegkeeten, froen no, wa se festhänken, a waarden ëmmer op däin Daum no uewen."]},{"n":55,"texts":["AI-gile ass eng Kanban-Tafel, wou d'Team aus KI-Agenten besteet. All Projet huet e Lead, deen d'Aarbecht plangt, an Hëllefer, déi se bauen. Wann eng Funktioun prett ass, probéiert en KI-Tester se aus a mécht e Screenshot, duerno landet se an dengem Stapel. Huel se un, oder kommentéier, an d'Team schafft se nei.","Et huet ugefaange mat enger Persoun, déi vill KI-Programméiersessiounen op eemol am Bléck wollt behalen, a gouf zu enger richteger Tafel. Si leeft op dengem Computer, brauch kee Kont a läit keng Tracker un. Si ass gratis fir Frënn a fir all, deen nei giereg ass. Si ass nach net fäerdeg, also erwaart rau Kanten an heiansdo eng Iwwerraschung.","Hei ass déi éierlech Versioun. Du muss nach ëmmer d'Iddie hunn, an du muss d'Resultater nach ëmmer kontrolléieren. Wat AI-gile mécht, ass alles dertëscht: et hält d'Kaarten an der Rei, erweckt dee richtegen Agent, wann s du kommentéiers, weist genee, wat geännert gouf, a sammelt alles an engem kuerze Stapel fir dech."]},{"n":89,"texts":["AI-gile ass eng gratis Kanban-Tafel, déi s du op dengem eegene Computer lafe léiss. Amplaz vu Leit huet all Projet e Team vun KI-Agenten: e Lead, deen deng Iddien a Kaarten an e Plang ëmwandelt, an Hëllefer, déi d'Kaarten no Prioritéit ofschaffen. Wann eppes gebaut ass, geet en KI-Tester d'Testschrëtt duerch a weist dir, wat en gesinn huet. Dunn waart et an engem Stapel mam Numm Fir dech. Du hëlls et un, oder du kommentéiers, an d'Team probéiert et nach eng Kéier. Näischt kënnt ouni dech bei Done.","E puer Funktiounen, un déi s du vläicht net denks. Eng Nuechtwuecht hält d'Kolonn Ze maachen gefëllt, während s du schléifs, a wielt Kaarten aus, déi keng Äntwert vun dir brauchen. En Token-Zieler weist, wéi vill d'Agenten haut an dës Woch gebraucht hunn, an de No Token Mode seet hinnen, si sollen oppassen. Du kanns Frënn schreiwen, a privat Noriichte sinn Enn-zu-Enn verschlësselt. D'Tafel schwätzt ongeféier 120 Sproochen, dorënner Hollännesch, Flämesch, Piroten a Klingonesch. Näischt dovun kascht eppes, a keen probéiert dir et ze verkafen.","AI-gile ass e klengt, perséinlecht Projet, keng Firma. De Rich wollt e puer KI-Programméierprojete bedreien, ouni all App opzemaachen, fir no all ze kucken, also hunn hien an d'Agenten eng Tafel dofir gebaut an duerno mat där Tafel de Rescht vun hirem Selwer. Si ass an der zouener Pre-Alpha, dat heescht, si funktionéiert, meeschtens, fir eng Handvoll Frënn. Et gëtt keng Präisssäit, keen Newsletter a kee Wuesstemsplang. Wann et nëtzlech kléngt, kanns du froen, ob s du et probéiere kanns, wann et e bësse méi opgeet."]},{"n":144,"texts":["AI-gile ass eng Kanban-Tafel fir ee Mënsch a ganz vill KI-Agenten. Si leeft op dengem eegene Computer a ass komplett gratis. Du setz Projeten un, an all Projet kritt e Lead an e klengt Team. Du schwätz mam Lead, ongeféier wéi bei Discord, a beschreifs eng Iddi; de Lead mécht Kaarten an e Plang dorausser a waart dann, bis s du op Go dréckss. D'Team schafft d'Kaarten no Prioritéit of, mat enger einfacher Kommandozeil, déi fir Sproochmodeller gemaach ass. Ier eppes bei dech zeréckkënnt, geet en KI-Tester d'Schrëtt an enger Kopie vun der App duerch a mécht e Screenshot derbäi. Fäerdeg Aarbecht landet an dengem Stapel, mat de geännerten Dateien an dem Ënnerscheed. Du hëlls se un, oder du léiss e Kommentar, an d'Team erwächt a probéiert et nach eng Kéier. Nëmmen du kanns eng Kaart op Done réckelen. Alles dat leeft op dengem Computer, ouni Konten, ouni Tracker an ouni Cookien.","E Dag mat AI-gile, ongeféier. Owes léiss du e puer Kommentarer: dëse Knäppchen ass um falsche Plaz, déi Lëscht soll sortéiert sinn, kéinte mir en donkelen Design hunn. Du gees schlofen. D'Agenten liesen d'Kommentarer, maache d'Ännerungen, testen se a ginn se dir zeréck. Wann Ze maachen eidel gëtt, fëllt d'Nuechtwuecht et aus dem Backlog mat Kaarten, déi keng Äntwert vun dir brauchen. Moies ass do ee kuerze Stapel: e puer Froen an e puer Saachen zum Probéieren, jidd mat Schrëtt, déi e schläfrege Mënsch kann nogoen, an engem Screenshot, dee weist, datt et funktionéiert. Du klicks dech duerch, hëlls dat Gutt un a schéckss de Rescht zeréck. En Token-Zieler weist, wat dat alles gebraucht huet, an de No Token Mode ass fir schmuel Wochen do. Dann hues du Fréistuck, wou d'Agenten nach net kënne hëllefen. An der Zäit schaffe se virun, an du hues ëmmer dat lescht Wuert.","Als Éischt, wat AI-gile net ass. Et ass kee Startup, et ass net ze verkafen, a keen sammelt deng Daten. Et ass eng gratis Tafel, déi op dengem Computer leeft, ouni Konten, ouni Tracker an ouni Cookien. Wat et ass: eng ordentlech Plaz, fir all KI-Programméierprojet op eemol ze gesinn, mat engem Team vun Agenten, dat d'Kaarten ofschafft, an dir, deen d'Decisiounen trëfft. Et fält verwandte Kaarten zesummen, flécket duerchenee Titelen a passt op, datt de Code schlank bleift. Et schwätzt ongeféier 120 Sproochen, vum Hollännesche a Flämesche bis zu Piroten a Klingonesch. Frënn kënnen sech schreiwen, privat a verschlësselt. Et gouf vum Rich a ganz villen gedëlleg Agenten gebaut, meeschtens mat sech selwer. Et ass an der zouener Pre-Alpha, dofir ass et op e puer Plazen rau. Wann et nom Spaass kléngt, frot léif, a vläicht kënns du fréi eran."]}],"quips":{"1":"Ee Wuert. Mutteg. Vläicht ze mutteg.","3":"Dräi Wierder. Elo schonn éierlecher wéi déi meescht Produktsäiten.","8":"Aacht Wierder. Ëmmer nach méi kuerz wéi e Stand-up.","21":"D'Längte sinn iwwregens Story Points. Natierlech sinn et dat.","55":"Fënnefafofzeg Wierder. Zwou Kaarten si fäerdeg ginn, während s du dat gelies hues.","144":"Dat ass déi laang. Et gëtt keng 233. D'Agenten sinn schlofe gaang."}},"timeline":{"first-idea.name":"Déi éischt Iddi","first-idea.line":"Dat allereschte Gespréich, ier et iwwerhaapt Code gouf.","first-board.name":"Déi éischt Tafel","first-board.line":"Eng Tafel, déi hiren eegene Bau verfollegt: Kaarten, Kolonnen, Zéien an Ofleeën, Projeten.","team-roles.name":"Team a Rollen","team-roles.line":"Agent-Profiler, Team-Virlagen, Raim a wien wat mécht.","install.name":"Installatioun a Versiounen","install.line":"E Zip, deen e Frënd installéiere kann, Selwer-Updates, Kanäl an Zeréckrollen.","usage-saver.name":"Verbrauchsspuerer","usage-saver.line":"Moosse, wat d'Lafe kaschten, de Code schlank halen, däi Limit schounen.","friends.name":"Frënn a Deelen","friends.line":"Privat DMs, e verschlësselte Relay, Invitatiounen, Rollen a gedeelte Projeten.","languages.name":"Sproochen","languages.line":"All Bildschierm-Text an enger Sproochdatei, mat Hollännesch a Flämesch als Éischt.","ai-tester.name":"KI-Tester","ai-tester.line":"E Tester kontrolléiert all Iwwergab als Éischt a weist, wat en gesinn huet.","website.name":"D'Websäit","website.line":"aigile.lol, den Teaser an dës Zäitleescht.","streaming.name":"Chat a Streaming","streaming.line":"Discord, Twitch, OBS, Streamer-Modus, GIFs an Emojien.","no-ai.name":"Editioun ouni KI","no-ai.line":"Eng Tafel fir Leit, déi ouni KI programméieren, an ëffentlech Tafelen.","night-watch.name":"Nuechtwuecht","night-watch.line":"E Wuechter an e Scrum Master halen d'Teams um Rees, während s du schléifs.","p-more.name":"Alles anescht","p-more.line":"Méi kleng Iddien, déi nach drun sinn.","p-android.name":"Telefon an Android","p-android.line":"Erreech deng Tafel vum Telefon aus, duerno mat enger eegener Android-App.","p-release.name":"Alpha a méi wäit","p-release.line":"Zouen Alpha, déi live Säit, dunn Beta.","p-languages.name":"Méi Sproochen","p-languages.line":"130 Sproochen, an e Sprooch-Immersiounsmodus fir Léierender.","p-engines.name":"Méi KI-Motoren","p-engines.line":"Wiel Claude, Codex, Gemini, Copilot oder Cursor fir all Agent.","p-pro.name":"Professionell Praxis","p-pro.line":"Risiko-Etiketten, Merge-Paarten, Incident-Kaarten a Leitplanken.","p-self.name":"Op dech oppassen","p-self.line":"Midd-Modus, Self-Care-Erënnerungen a 4:20.","p-servers.name":"Serveren a Wuesstem","p-servers.line":"Global Serveroptiounen, Rollen a Planung fir de Wuesstem.","p-livestream.name":"Streaming-Extrae","p-livestream.line":"Twitch-Chat, eege Emojien an eng ëffentlech Live-Usiicht."},"words":{"button":"📖 Fachbegrëffer","h":"📖 Wierder erkläert","intro":"D'Wierder, déi s du an AI-gile begéins, an einfacher Sprooch: et bauen, et sécher änneren, et fir d'Leit, déi et notzen, um Lafen halen, an als Team mat KI schaffen.","search":"E Wuert sichen…","none":"Kee Wuert passt dozou.","close":"Zoumaachen","count":{"one":"{count} Wuert","other":"{count} Wierder"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Et bauen"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Et sécher änneren"},{"id":"run","name":"🛎️ E Service bedreiwen"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Iddien an Aarbecht, déi nach net ageplangt sinn. Do gëtt näischt gemaach, bis et op Ze maachen geréckelt gëtt."},{"id":"sprint","g":"agile","word":"Sprint","text":"E kuerzen Zäitraum vun Aarbecht (dacks eng Woch oder zwou) mat engem ofgemaachte Set vu Kaarten, déi fäerdeg solle ginn.","also":["Sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"E séiere Check-in: wat all Teammember gemaach huet, wat e loossgeet, a wat en ophält.","also":["Standup","Stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"E Board mat Kolonnen (Ze maachen, Amgaang, Fäerdeg), wou d'Kaarte vu lénks no riets réckelen, wéi d'Aarbecht geschitt."},{"id":"wip","g":"agile","word":"WIP-Limit","text":"Work in progress: déi meescht Kaarten, déi eng Kolonn halen soll, fir datt d'Team d'Saache fäerdeg mécht, éier et méi ufänkt.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Dem Team seng kuerz Checklëscht dofir, wat „fäerdeg“ heescht, wéi getest an erkläert, ier eng Kaart dir iwwerginn gëtt. Hiren Zwilling, d'Definition of Ready, seet, wéini eng Kaart kloer genuch ass, fir unzefänken.","also":["Definition of Ready"]},{"id":"retro","g":"agile","word":"Réckbléck","text":"E Bléck zréck op d'Aart a Weis, wéi d'Team schafft, fir sech op eng Saach ze eenegen, déi et besser maache wëll. An AI-gile schléit e Réckbléck eng Ännerung un der Aarbechtsweis vum Team vir, an du sees Go oder Nach net.","also":["Retro","Retrospektiv"]},{"id":"swarm","g":"agile","word":"Schwarm","text":"All Mann un d'Deck: all Team leet aner Aarbecht op d'Säit, fir engem dréngende Projet ze hëllefen, bis e geléist ass. Aner Projete waarden esoulaang.","also":["Swarm","Swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Deen, deen d'Aarbecht am Floss hält: gesäit Kaarten, déi hänke bleiwen, stupst d'Teams un an erënnert dech drun, wat op dech waart. An AI-gile mécht de Lead Scrum Master dat iwwer all Projet ewech.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Den Dossier vum Projet mam Code a senger ganzer Geschicht vu Commits, meeschtens och op GitHub gehal.","also":["Repository"]},{"id":"branch","g":"build","word":"Branch","text":"Eng getrennte Linn vun Aarbecht am Code, fir Ännerunge kënne ze maachen, ouni d'Haaptversioun unzefaassen.","also":["Branches"]},{"id":"commit","g":"build","word":"Commit","text":"E gespäichert Snapshot vum Code, mat enger kuerzer Notiz, wat sech geännert huet. Du kanns ëmmer op een zréckgoen.","also":["Commits"]},{"id":"push","g":"build","word":"Push","text":"Gespäichert Snapshots (Commits) vun dësem Computer op GitHub eropschécken, fir datt se gesécher a gedeelt sinn."},{"id":"merge","g":"build","word":"Merge","text":"D'Ännerunge vun engem Branch zréck an d'Haaptversioun zesummeféieren."},{"id":"pr","g":"build","word":"Pull Request","text":"Froen, datt d'Ännerunge vun engem Branch kontrolléiert an an d'Haaptversioun gemergt ginn.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"De Code opraumen, ouni dass sech ännert, wat e mécht: méi kleng Dateien, méi kloer Nimm, manner Widderhuelung."},{"id":"bug","g":"build","word":"Bug","text":"Eppes, wat net esou funktionéiert, wéi et sollt.","also":["Bugs"]},{"id":"peerreview","g":"build","word":"Peer-Review","text":"En zweet Paar Aen: eng aner KI kontrolléiert d'Aarbecht vun all Kaart, ier se bei dir ukënnt, sou datt manner Feeler duerchrutschen.","also":["Code-Review","Peer Review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"E fäerdegt Stéck Aarbecht ausprobéieren, fir ze kucken, ob et mécht, wat gefrot gouf, ier s du et akzeptéiers.","also":["Tester","Testen","testen"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kuerz fir quality assurance, also Qualitéitssécherung: déi automatesch Kontrollen, déi lafen, ier eppes live geet. Wann d'QA rout ass, ass eppes feelgeschloen, an et kann net live goen, bis dat behuewen ass.","also":["Qualitéitskontroll","Qualitéitssécherung"]},{"id":"testpile","g":"test","word":"Test-Stapel","text":"Déi fäerdeg Kaarten, déi drop waarden, datt s du se ausprobéiers, eng no der anerer. Akzeptéier eng oder schéck se mat enger Notiz zréck, an déi nächst kënnt.","also":["Test-Stapelen"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Eng nei Versioun live setzen, zum Beispill op e Server, wou d'Leit se notzen."},{"id":"release","g":"change","word":"Verëffentlechung","text":"E benannte Pak vu fäerdeger Aarbecht, deen zesumme live geet, mat kuerzen Notizen iwwer dat, wat geännert huet. 🚀 Verëffentlechunge schreift d'Notizen aus de fäerdege Kaarten.","also":["Verëffentlechungen","Release"]},{"id":"rollback","g":"change","word":"Zréckrollen","text":"Zréck op déi lescht Versioun, déi funktionéiert huet, wann eng nei Versioun Ierger mécht. An AI-gile mécht et eng Checklëscht aus de Schrëtt fir d'Réckgängegmaachen, déi op all Ännerung geschriwwe sinn.","also":["Rollback","zréckgerollt"]},{"id":"live","g":"change","word":"Live","text":"Déi richteg Versioun, déi d'Leit notzen, am Géigesaz zu enger Kopie fir Saachen auszeprobéieren. Entwéckler soen och Produktioun dozou.","also":["Produktioun","production"],"noTip":1},{"id":"change","g":"change","word":"Ännerung","text":"Eng geplangten Ännerung un eppes, op dat d'Leit sech verloossen, als éischt opgeschriwwen: wat, firwat, de Risiko, wéini a wéi een et réckgängeg mécht. Fänk eng mat 🔀 Ännerung ufroen un.","also":["Ännerungen","Ännerungsufro"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Eppes, wat schif goe kéint, bewäert no deem, wéi wahrscheinlech an wéi schlëmm et wier. ⚠️ Risiken hält se an enger Lëscht, déi héchste Bewäertung fir d'éischt, all eenzel mat engem Datum fir nach eng Kéier nozekucken.","also":["Risiken","Risikoregister"]},{"id":"chgwin","g":"change","word":"Ännerungsfënster","text":"D'Zäiten, wou Ännerunge live goe dierfen, zum Beispill e rouegen Dënschdegowend. Ausserhalb vun enger Fënster kann eng Ännerungskaart net ofgeschloss ginn, ausser et ass en Noutfall.","also":["Ännerungsfënsteren","Change Window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Eng séier Ofstëmmung just ier eng Ännerung live geet: jidderee, deen zoustëmme muss, seet Go oder No go. Et geet just weider, wann all d'accord sinn.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Genehmegung","text":"Op e Jo waarden, ier d'Aarbecht ufänkt. Eng Kaart, déi e Frënd opmécht, oder eng Ännerung, waart an ✅ Genehmegungen, bis s du se genehmegs oder ofleens.","also":["Genehmegungen"]},{"id":"quiettime","g":"change","word":"Rouzäit","text":"Eng Zäitspan, wéi e Stream, eng Demo oder d'Nuecht, wou näischt live geet. D'Teams schaffen an testen weider, mee d'Live-Goen waart, bis se eriwwer ass. Soss nennt een dat och en Ännerungsstopp (change freeze).","also":["Rouzäiten","Change Freeze","Ännerungsstopp"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Eppes, wat s du gebaut hues an op dat d'Leit sech verloossen, wéi eng Websäit oder eng App, a wat gefleegt gëtt, fir datt et weider funktionéiert. Kräiz „Dëst Projet ass e Service“ un a so, wat en ubitt, wien en notzt a wien Bereetschaft huet.","also":["Servicer"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Verfügbarkeetskontroll","text":"Eng automatesch Kontroll, all puer Minutten, ob däi Service nach äntwert. Wann se e puer Mol hannereneen feelschléit, mécht AI-gile vu sech aus eng Zwëschefall-Kaart op.","also":["Verfügbarkeet","Uptime"]},{"id":"statuspage","g":"run","word":"Statussäit","text":"Eng ëffentlech Säit, déi weist, ob e Service funktionéiert (gréng, orange oder rout), mat der leschter Neiegkeet, sou datt d'Leit, déi en notzen, do nokucke kënnen amplaz ze froen.","also":["Statussäiten","Status Page"]},{"id":"desk","g":"run","word":"Service-Schalter","text":"Do, wou d'Froen an d'Meldunge vun de Leit ukommen, déi däi Service benotzen. AI-gile sortéiert all eenzel als Ufro, Incident oder Iddi a seet et, wann et no eppes ausgesäit, dat schonn gemellt gouf.","also":["Service-Schalteren","Helpdesk","Service Desk"]},{"id":"svcrequest","g":"run","word":"Service-Ufro","text":"Een freet no eppes Normalem, wéi engem neie Kont oder e bësse Hëllef, amplaz ze mellen, datt eppes futti ass. Se waart, bis se drun ass; en Incident geet vir.","also":["Service-Ufroen","Ufro"]},{"id":"incident","g":"run","word":"Zwëschefall","text":"Eppes, wat elo grad fir d'Leit, déi et notzen, futti ass, wéi eng Websäit, déi net erreechbar ass. Eng 🔥 Zwëschefall-Kaart spréngt an der Rei no vir: et erëm lafen ze kréien, kënnt virun allem.","also":["Zwëschefäll","Incident","Virfall"]},{"id":"major","g":"run","word":"Gréisse Virfall","text":"E grousse Zwëschefall: vill Leit si betraff, oder Suen oder Daten a Gefor. Ee Knäppchen setzt all Team drun (Schwarm), weckt deen, deen Bereetschaft huet, a freet all 30 Minutten no engem Statusupdate.","also":["grousse Zwëschefall","Major Incident"]},{"id":"oncall","g":"run","word":"Bereetschaft","text":"Deen ze sinn, deen äntwert, wann eppes futti geet, och an der Nuecht. All Service huet en Teammember mat Bereetschaft, deen als éischte fir seng Zwëschefäll geweckt gëtt.","also":["op Ruff","On call","On-call"]},{"id":"replyby","g":"run","word":"Äntwertzäit","text":"Wéi laang eng Kaart op eng éischt Äntwert waarde kann, zum Beispill eng Stonn fir e Zwëschefall. Duerno kritt se eng rout Auer, sou datt näischt roueg vergiess gëtt. Och Äntwertziel genannt.","also":["Äntwertzäiten","Äntwertziel","Response Target"]},{"id":"postmortem","g":"run","word":"Post-Mortem","text":"E kuerze Réckbléck no engem Zwëschefall: wat geschitt ass, wat gehollef huet a wat ee soll änneren, ouni engem d'Schold ze ginn. E Zwëschefall kann net ouni een zougemaach ginn.","also":["Post-mortem","Postmortem","Réckbléck nom Zwëschefall"]},{"id":"problem","g":"run","word":"Problem","text":"Déi verstoppten Ursaach hannert engem oder méi Zwëschefäll. Eng 🧩 Problem-Kaart gruppéiert Zwëschefäll, déi ëmmer erëm kommen, sou datt d'Ursaach fonnt a fir ëmmer behuewe gëtt.","also":["Problemer"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondursaach","text":"De richtege Grond, firwat eppes futti gaangen ass, net just dat, wat s du schif goe gesinn hues. Behief d'Grondursaach, an de Zwëschefall kënnt net méi erëm.","also":["Grondursaachen","Root Cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"E Behëllef, fir datt alles weider leeft, bis déi richteg Léisung prett ass, wéi eppes nei starten, wann et hänke bleift. En gëtt op d'Problem-Kaart geschriwwen, sou datt keen en nach eng Kéier muss erausfannen.","also":["Behëllef","Workarounds"]},{"id":"knownerror","g":"run","word":"Bekannte Feeler","text":"E Problem, deem seng Ursaach verstan ass an deen e Workaround huet, mee nach net behuewen ass. 🧩 Bekannt Feeler lëscht se op, sou datt jiddereen de Workaround benotzt, amplaz nach eng Kéier ze sichen.","also":["bekannt Feeler","Known Error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Schrëtt-fir-Schrëtt-Instruktiounen, fir eng bekannt Zort Ierger ze behiewen, sou datt et all Kéier d'selwecht a séier gemaach gëtt. No engem grousse Zwëschefall kann d'Team der eent virschloen, an du gëss däin OK.","also":["Runbooks"]},{"id":"ci","g":"run","word":"Konfiguratiounselement","text":"Eng Saach, op där däi Service berout, wéi e Server, en Domain, en Zertifikat, e Schlëssel oder e Lieferant. 🗂️ Konfiguratiounselementer lëscht se pro Service op, sou datt s du gesäis, wat en Incident betrëfft a wat erneiert oder gesäichert muss ginn.","also":["Konfiguratiounselementer","Configuration Item","CI"]},{"id":"expiry","g":"run","word":"Oflafdatum","text":"AI-gile hält en A op Datumer, wéi wann en Zertifikat oder en Domain ofleeft. 30 Deeg virum Datum mécht et eng Kaart fir z'erneieren, sou datt näischt op eemol ophält ze fonctionéieren.","also":["Oflafdatumer","Oflaf","Oflafiwwerwaachung"]},{"id":"backup","g":"run","word":"Sécherung","text":"Eng gespäichert Kopie vun dengen Daten vu virdrun, op déi s du zréckgräife kanns, wann eppes verluer geet oder beschiedegt gëtt. AI-gile mécht all Dag eng Sécherung vun denge Bierder.","also":["Sécherungen","Backup"]},{"id":"restore","g":"run","word":"Erëmhierstellen","text":"Daten aus enger Sécherung zréckspillen. Eng Sécherung zielt eréischt richteg, wann s du weess, datt een se erëmhierstelle kann, also lount et sech, dat ab an zou ze probéieren.","also":["erëmhiergestallt","Restore"]},{"id":"svcreview","g":"run","word":"Service-Review","text":"E Réckbléck op ee Mount vun engem Service: opgemaachen a gefléckten Incidenter, wéi séier d'Leit eng Äntwert kruten, Verfügbarkeet a verbrauchten Tokens. De Monatleche Review weist dat fir all Service.","also":["Service-Reviewen","Monatleche Review","monatleche Review"]},{"id":"accessreview","g":"run","word":"Zougangsiwwerpréiwung","text":"All 90 Deeg kucken, wien nach eraka: Deel-Linken, Rolle vu Frënn a gespäichert Geheimnisser. Du behäls oder hëls all eenzel ewech, sou datt keen alen Zougang hänke bleift.","also":["Zougangsiwwerpréiwungen","Access Review"]},{"id":"improvements","g":"run","word":"Verbesserungslëscht","text":"Alles, wat d'Team decidéiert huet besser ze maachen, op enger Plaz: Retro-Virschléi, Review-Aktiounen a Problem-Léisungen, all mat sengem Status. Du fënns se ënner 📈 Verbesserungen.","also":["Verbesserungslëschten","Verbesserungen"]},{"id":"tokencap","g":"run","word":"Token-Limit","text":"Eng monatlech Limit fir d'Tokens, déi d'Agente vun engem Service benotze kënnen. Bei 80% kriss du eng Warnung; bei 100% waart hir Aarbecht am Hannergrond bis den nächste Mount oder bis s du d'Limit erhéichs.","also":["Token-Limitten","monatlech Token-Limit"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Eng KI, déi eleng un enger Aufgab schafft: liest de Code, mécht Ännerungen, féiert Kontrolle aus a mellt sech zeréck.","also":["Agenten","Agents"]},{"id":"token","g":"ai","word":"Token","text":"D'Eenheet, an där d'KI-Notzung gezielt gëtt: ongeféier e puer Buschtawen Text, gelies oder geschriwwen. Manner Tokens, méi bleift vun dengem Plang iwwreg.","also":["Tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"E klenge Kommando, deen zu engem festgeluechte Moment vu sech aus leeft, z. B. wann eng KI-Sessioun ufänkt, fir datt d'Team deng Kommentarer héiert.","also":["Hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
